// Sandbox test webpage -- GET /sandbox-roles
// Returns the *actual* list of contact roles the database currently allows
// (parsed live from the contacts.role CHECK constraint via the
// contact_role_options() RPC -- see supabase/schema.sql), not a hardcoded
// list here. If schema.sql ever grows the allowed-roles list, this follows
// automatically the next time it's applied -- the sandbox's "add a persona"
// picker is never out of date with what the real app actually accepts.
const helpers = this.helpers;
const env = { SUPABASE_URL: $env.SUPABASE_URL, SUPABASE_KEY: $env.SUPABASE_SERVICE_KEY };

const roles = await helpers.httpRequest({
  method: 'POST',
  url: `${env.SUPABASE_URL}/rest/v1/rpc/contact_role_options`,
  headers: {
    apikey: env.SUPABASE_KEY,
    Authorization: `Bearer ${env.SUPABASE_KEY}`,
    'Content-Type': 'application/json',
  },
  body: {},
  json: true,
  timeout: 15000,
});

return [{ json: { roles: roles || [] } }];

// Sandbox test webpage -- GET /sandbox-personas
// Lists every fake persona currently in the sandbox database, so the test
// page always reflects exactly who exists right now -- add one, it shows up
// here on the next poll, no page rebuild needed.
const helpers = this.helpers;
const env = { SUPABASE_URL: $env.SUPABASE_URL, SUPABASE_KEY: $env.SUPABASE_SERVICE_KEY };

const contacts = await helpers.httpRequest({
  method: 'GET',
  url: `${env.SUPABASE_URL}/rest/v1/contacts?select=id,name,phone_number,role&order=created_at.asc`,
  headers: { apikey: env.SUPABASE_KEY, Authorization: `Bearer ${env.SUPABASE_KEY}` },
  json: true,
  timeout: 15000,
});

return [{ json: { personas: contacts || [] } }];

// Sandbox test webpage -- POST /sandbox-persona
// Creates a new fake persona (any role the database currently allows -- see
// sandbox-roles-code.js) with a made-up phone number, so testing never needs
// a real number for anyone. Body: { name, role }.
const helpers = this.helpers;
const env = { SUPABASE_URL: $env.SUPABASE_URL, SUPABASE_KEY: $env.SUPABASE_SERVICE_KEY };
const sbHeaders = { apikey: env.SUPABASE_KEY, Authorization: `Bearer ${env.SUPABASE_KEY}` };

// Snapshot every sandbox table before this action so it can be undone on its
// own via /sandbox-undo, one action at a time, instead of the all-or-nothing
// /sandbox-reset. See sandbox-undo-code.js for how a snapshot gets restored.
const SNAPSHOT_TABLES = ['contacts', 'bookings', 'conversations', 'pending_questions', 'invoices', 'contracts', 'knowledge_base', 'sandbox_outbound'];
async function takeSnapshot(label) {
  const tables_json = {};
  for (const table of SNAPSHOT_TABLES) {
    tables_json[table] = await helpers.httpRequest({
      method: 'GET',
      url: `${env.SUPABASE_URL}/rest/v1/${table}?select=*`,
      headers: sbHeaders,
      json: true,
      timeout: 15000,
    });
  }
  await helpers.httpRequest({
    method: 'POST',
    url: `${env.SUPABASE_URL}/rest/v1/sandbox_snapshots`,
    headers: { ...sbHeaders, 'Content-Type': 'application/json' },
    body: { label, tables_json },
    json: true,
    timeout: 15000,
  });
}

const input = $input.first().json.body || {};

const name = (input.name || '').trim();
const role = (input.role || '').trim();
if (!name || !role) {
  return [{ json: { error: 'name and role are both required' } }];
}

await takeSnapshot(`Create persona "${name}" (${role})`);

// 234000 is the existing convention in this codebase for obviously-fake test
// numbers (never a real, dialable number) -- see docs/setup.md's note on
// synthetic 234000000xxxx contacts used throughout live testing.
const fakeNumber = `234000${String(Math.floor(Math.random() * 900000) + 100000)}`;

const created = await helpers.httpRequest({
  method: 'POST',
  url: `${env.SUPABASE_URL}/rest/v1/contacts`,
  headers: {
    apikey: env.SUPABASE_KEY,
    Authorization: `Bearer ${env.SUPABASE_KEY}`,
    'Content-Type': 'application/json',
    Prefer: 'return=representation',
  },
  body: { name, role, phone_number: fakeNumber },
  json: true,
  timeout: 15000,
});

return [{ json: { persona: created?.[0] || created } }];

// Sandbox test webpage -- POST /sandbox-send
// Takes a message typed "as" a given persona and feeds it into the exact
// same inbound router (01-inbound-router.json) the real app uses -- built as
// a Meta-Cloud-API-shaped payload, same as what Nexa forwards for real
// traffic, so every bit of real routing/role logic gets exercised for real,
// not reimplemented here. Body: { phone_number, text }.
const helpers = this.helpers;
const env = {
  N8N_BASE_URL: $env.N8N_BASE_URL,
  FORWARD_SECRET: $env.BALI_FORWARD_SECRET,
  SUPABASE_URL: $env.SUPABASE_URL,
  SUPABASE_KEY: $env.SUPABASE_SERVICE_KEY,
};
const sbHeaders = { apikey: env.SUPABASE_KEY, Authorization: `Bearer ${env.SUPABASE_KEY}` };

// Snapshot every sandbox table before this action so it can be undone on its
// own via /sandbox-undo, one action at a time, instead of the all-or-nothing
// /sandbox-reset. One "send" can cascade through several tables (booking
// fields, conversations, pending_questions, invoices...) via the real
// pipeline below -- taking the snapshot right before dispatching it captures
// state as of "before this one action", however much it goes on to touch.
// See sandbox-undo-code.js for how a snapshot gets restored.
const SNAPSHOT_TABLES = ['contacts', 'bookings', 'conversations', 'pending_questions', 'invoices', 'contracts', 'knowledge_base', 'sandbox_outbound'];
async function takeSnapshot(label) {
  const tables_json = {};
  for (const table of SNAPSHOT_TABLES) {
    tables_json[table] = await helpers.httpRequest({
      method: 'GET',
      url: `${env.SUPABASE_URL}/rest/v1/${table}?select=*`,
      headers: sbHeaders,
      json: true,
      timeout: 15000,
    });
  }
  await helpers.httpRequest({
    method: 'POST',
    url: `${env.SUPABASE_URL}/rest/v1/sandbox_snapshots`,
    headers: { ...sbHeaders, 'Content-Type': 'application/json' },
    body: { label, tables_json },
    json: true,
    timeout: 15000,
  });
}

const input = $input.first().json.body || {};

const phoneNumber = (input.phone_number || '').trim();
const text = (input.text || '').trim();
if (!phoneNumber || !text) {
  return [{ json: { error: 'phone_number and text are both required' } }];
}

await takeSnapshot(`Send "${text}"`);

const messageId = `sandbox-wamid-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;

await helpers.httpRequest({
  method: 'POST',
  url: `${env.N8N_BASE_URL}/webhook/whatsapp-inbound`,
  headers: { 'Content-Type': 'application/json', 'x-bali-forward-secret': env.FORWARD_SECRET },
  body: {
    entry: [{
      changes: [{
        value: {
          messages: [{
            from: phoneNumber,
            id: messageId,
            timestamp: String(Math.floor(Date.now() / 1000)),
            type: 'text',
            text: { body: text },
          }],
        },
      }],
    }],
  },
  json: true,
  timeout: 15000,
});

return [{ json: { ok: true, whatsapp_message_id: messageId } }];

// Sandbox test webpage -- GET /sandbox-poll?since=<ISO timestamp>
// Returns everything the bot would have sent out over real WhatsApp since
// the given time (captured in sandbox_outbound by the SANDBOX guards added
// to every sendWhatsApp*/uploadWhatsAppMedia function -- see the comment atop
// each _src file's SANDBOX const). The page polls this and routes each
// message into the matching persona's chat window by phone number.
const helpers = this.helpers;
const env = { SUPABASE_URL: $env.SUPABASE_URL, SUPABASE_KEY: $env.SUPABASE_SERVICE_KEY };
const since = $input.first().json.query?.since || '1970-01-01T00:00:00Z';

const rows = await helpers.httpRequest({
  method: 'GET',
  url: `${env.SUPABASE_URL}/rest/v1/sandbox_outbound?created_at=gt.${encodeURIComponent(since)}&order=created_at.asc&select=*`,
  headers: { apikey: env.SUPABASE_KEY, Authorization: `Bearer ${env.SUPABASE_KEY}` },
  json: true,
  timeout: 15000,
});

return [{ json: { messages: rows || [], polled_at: new Date().toISOString() } }];

// Sandbox test webpage -- POST /sandbox-reset
// Wipes every sandbox-only table back to empty, so a scenario can be re-run
// from a clean slate as many times as needed. Deletes in FK-safe order
// (children before parents). Never touches the real app's data -- this Code
// node's SUPABASE_URL always points at the sandbox database, never the live
// one (see n8n's docker-compose sandbox-n8n service definition).
const helpers = this.helpers;
const env = { SUPABASE_URL: $env.SUPABASE_URL, SUPABASE_KEY: $env.SUPABASE_SERVICE_KEY };
const headers = { apikey: env.SUPABASE_KEY, Authorization: `Bearer ${env.SUPABASE_KEY}`, 'Content-Type': 'application/json' };

async function wipe(table) {
  return helpers.httpRequest({
    method: 'DELETE',
    url: `${env.SUPABASE_URL}/rest/v1/${table}?id=not.is.null`,
    headers,
    timeout: 15000,
  });
}

for (const table of ['conversations', 'pending_questions', 'invoices', 'contracts', 'knowledge_base', 'sandbox_outbound', 'bookings', 'contacts', 'sandbox_snapshots']) {
  await wipe(table);
}

return [{ json: { ok: true, reset_at: new Date().toISOString() } }];

// Sandbox test webpage -- POST /sandbox-undo
// Pops the most recent snapshot (taken automatically before every mutating
// sandbox action -- see takeSnapshot() in sandbox-send-code.js and
// sandbox-persona-create-code.js) and restores every sandbox table to
// exactly how it looked right before that one action. Repeatable -- each
// call undoes one more step back, unlike /sandbox-reset which wipes
// everything to empty in one go.
const helpers = this.helpers;
const env = { SUPABASE_URL: $env.SUPABASE_URL, SUPABASE_KEY: $env.SUPABASE_SERVICE_KEY };
const headers = { apikey: env.SUPABASE_KEY, Authorization: `Bearer ${env.SUPABASE_KEY}`, 'Content-Type': 'application/json' };

// Parent-first, safe for re-inserting. Deletes run in the reverse order
// (children before parents), same convention as sandbox-reset-code.js.
const TABLE_ORDER = ['contacts', 'bookings', 'conversations', 'pending_questions', 'invoices', 'contracts', 'knowledge_base', 'sandbox_outbound'];

const snapshots = await helpers.httpRequest({
  method: 'GET',
  url: `${env.SUPABASE_URL}/rest/v1/sandbox_snapshots?order=id.desc&limit=1&select=*`,
  headers,
  json: true,
  timeout: 15000,
});
const snapshot = snapshots[0];
if (!snapshot) {
  return [{ json: { ok: false, message: 'Nothing to undo.' } }];
}

for (const table of [...TABLE_ORDER].reverse()) {
  await helpers.httpRequest({
    method: 'DELETE',
    url: `${env.SUPABASE_URL}/rest/v1/${table}?id=not.is.null`,
    headers,
    timeout: 15000,
  });
}
for (const table of TABLE_ORDER) {
  const rows = snapshot.tables_json[table] || [];
  if (rows.length === 0) continue;
  await helpers.httpRequest({
    method: 'POST',
    url: `${env.SUPABASE_URL}/rest/v1/${table}`,
    headers,
    body: rows,
    json: true,
    timeout: 15000,
  });
}

await helpers.httpRequest({
  method: 'DELETE',
  url: `${env.SUPABASE_URL}/rest/v1/sandbox_snapshots?id=eq.${snapshot.id}`,
  headers,
  timeout: 15000,
});

const remaining = await helpers.httpRequest({
  method: 'GET',
  url: `${env.SUPABASE_URL}/rest/v1/sandbox_snapshots?select=id`,
  headers,
  json: true,
  timeout: 15000,
});

return [{ json: { ok: true, undone: snapshot.label, remaining: remaining.length } }];

// Sandbox test webpage -- GET /sandbox-undo-count
// How many undo steps are currently available, for the webpage to show next
// to the Undo button (and disable it at zero) without guessing client-side.
const helpers = this.helpers;
const env = { SUPABASE_URL: $env.SUPABASE_URL, SUPABASE_KEY: $env.SUPABASE_SERVICE_KEY };

const rows = await helpers.httpRequest({
  method: 'GET',
  url: `${env.SUPABASE_URL}/rest/v1/sandbox_snapshots?select=id`,
  headers: { apikey: env.SUPABASE_KEY, Authorization: `Bearer ${env.SUPABASE_KEY}` },
  json: true,
  timeout: 15000,
});

return [{ json: { count: rows.length } }];
